using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using Microsoft.Extensions.Logging;

namespace FileProcessingService
{
    public class FeatureFlags
    {
        private readonly Dictionary<string, bool> _flags;

        public FeatureFlags()
        {
            _flags = new Dictionary<string, bool>
            {
                { "enhanced_logging", true },
                { "structured_output", true },
                { "legacy_encoding", false },
                { "audit_trail", true }
            };
        }

        public bool IsEnabled(string flag) => _flags.ContainsKey(flag) && _flags[flag];
    }

    public interface ILogSanitizer
    {
        string Sanitize(string input);
    }

    public class LogSanitizer : ILogSanitizer
    {
        private static readonly Regex CrlfPattern = new Regex(@"[\r\n]", RegexOptions.Compiled);

        public string Sanitize(string input)
        {
            if (string.IsNullOrEmpty(input)) return input;
            return CrlfPattern.Replace(input, "_");
        }
    }

    public class AuditEncoder
    {
        private readonly FeatureFlags _features;

        public AuditEncoder(FeatureFlags features)
        {
            _features = features;
        }

        public string EncodeForAudit(string rawValue)
        {
            if (_features.IsEnabled("legacy_encoding"))
            {
                return Convert.ToBase64String(Encoding.UTF8.GetBytes(rawValue));
            }

            // "Modern" encoding: normalize Unicode then pass through
            var normalized = rawValue.Normalize(NormalizationForm.FormKC);
            return normalized;
        }
    }

    public class FileMetadataExtractor
    {
        public string ExtractDisplayName(string filePath)
        {
            var fileName = Path.GetFileName(filePath);
            // Decode any URL-encoded characters in filename for display
            return Uri.UnescapeDataString(fileName);
        }
    }

    public class FileProcessingHandler
    {
        private readonly ILogger<FileProcessingHandler> _logger;
        private readonly FeatureFlags _features;
        private readonly ILogSanitizer _sanitizer;
        private readonly AuditEncoder _auditEncoder;
        private readonly FileMetadataExtractor _metadataExtractor;

        public FileProcessingHandler(
            ILogger<FileProcessingHandler> logger,
            FeatureFlags features,
            ILogSanitizer sanitizer)
        {
            _logger = logger;
            _features = features;
            _sanitizer = sanitizer;
            _auditEncoder = new AuditEncoder(features);
            _metadataExtractor = new FileMetadataExtractor();
        }

        public ProcessingResult ProcessFile(string filePath, string uploadedBy)
        {
            var result = new ProcessingResult();

            try
            {
                // Step 1: Extract metadata
                var displayName = _metadataExtractor.ExtractDisplayName(filePath);

                // Step 2: Sanitize for logging
                var sanitizedName = _sanitizer.Sanitize(displayName);
                var sanitizedUser = _sanitizer.Sanitize(uploadedBy);

                // Step 3: Encode for audit trail
                var auditName = _auditEncoder.EncodeForAudit(sanitizedName);
                var auditUser = _auditEncoder.EncodeForAudit(sanitizedUser);

                // Step 4: Log based on feature flags
                if (_features.IsEnabled("enhanced_logging"))
                {
                    _logger.LogInformation(
                        "Processing file: {FileName} uploaded by: {User}",
                        sanitizedName, sanitizedUser);
                }

                if (_features.IsEnabled("audit_trail"))
                {
                    WriteAuditLog(auditName, auditUser);
                }

                result.Success = true;
                result.Message = $"Processed {sanitizedName}";
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error processing file");
                result.Success = false;
                result.Message = "Processing failed";
            }

            return result;
        }

        private void WriteAuditLog(string fileName, string user)
        {
            var timestamp = DateTime.UtcNow.ToString("o");
            var logLine = $"[{timestamp}] FILE_PROCESSED | name={fileName} | user={user}";

            // Audit log written to dedicated file
            File.AppendAllText("/var/log/fileservice/audit.log", logLine + Environment.NewLine);
        }
    }

    public class ProcessingResult
    {
        public bool Success { get; set; }
        public string Message { get; set; }
    }
}
